    pm.expect(pm.response.json().method).to.eql("POST");
});
const schema = {
    type: "object",
    required: ["method", "json", "headers"],
    properties: {
        method:  { type: "string" },
        json:    { type: "object" },
        headers: { type: "object" },
        url:     { type: "string" }
    }
};

pm.test("响应结构符合 schema", function () {
    pm.response.to.have.jsonSchema(schema);
});
pm.test("回显的 name 和我发的一致", function () {
    pm.expect(pm.response.json().json.name).to.eql("张三");
});

pm.test("回显的 tags 是数组且长度为 2", function () {
    pm.expect(pm.response.json().json.tags).to.be.an("array").and.have.lengthOf(2);
});

pm.test("状态码是 200", function () {
    pm.response.to.have.status(200);
});
pm.test("无 cookie 时返回空对象", function () {
    pm.expect(pm.response.json().cookies).to.eql({});
});

pm.test("服务端收到了这个 cookie", function () {
    pm.expect(pm.response.json().cookies.session).to.eql("abc123");
});

const body = pm.response.json();

// 存进集合变量
pm.collectionVariables.set("uid", body.uuid);

pm.test("uuid 已存入变量", function () {
    pm.expect(pm.collectionVariables.get("uid")).to.be.a("string").and.not.empty;
});
pm.test("状态码是 200", function () {
    pm.response.to.have.status(200);
});

pm.test("服务器收到了这个 uuid", function () {
    pm.expect(pm.response.json().args.uid)
      .to.eql(pm.collectionVariables.get("uid"));
});
pm.test("状态码是 200", function () {
    pm.response.to.have.status(200);
});

if (!pm.collectionVariables.get("uid")) {
    console.warn("uid 为空：06 必须在 05 之后跑");
}

const args = pm.response.json().args;

pm.test("uuid 是合法格式", function () {
    pm.expect(args.u).to.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
});

pm.test("timestamp 是正整数", function () {
    pm.expect(Number(args.t)).to.be.above(0);
});

pm.test("n 在 0-1000 之间", function () {
    pm.expect(Number(args.n)).to.be.within(0, 1000);
});

pm.test("服务端错误返回 500", function () {
    pm.response.to.have.status(500);
});
pm.test("错误响应没有 body", function () {
    pm.expect(pm.response.text()).to.be.empty;
});

pm.test("资源不存在返回 404", function () {
    pm.response.to.have.status(404);
});
pm.test("错误响应没有 body", function () {
    pm.expect(pm.response.text()).to.be.empty;
});

